/** Alias for consumers that display the Python API table. */
export const signatures = SIGNATURES;

/** Resolve a facade path, including RobotSession's arm attribute forwarding. */
export function resolveSpec(path) {
  if (path === 'connect') return SIGNATURES.connect;
  const bits = path.split('.');
  const classes = { arm: 'MoveIt2', gripper: 'GripperInterface', servo: 'MoveIt2Servo', description: 'RobotDescription' };
  const cls = classes[bits[1]] ?? 'RobotSession';
  const name = classes[bits[1]] ? bits[2] ?? '__call__' : bits[1];
  return SIGNATURES[cls].methods[name] ?? SIGNATURES[cls].properties[name] ?? (cls === 'RobotSession' ? SIGNATURES.MoveIt2.methods[name] ?? SIGNATURES.MoveIt2.properties[name] : undefined);
}
